import adel from '@/assets/imgs/user.png';
import { useEffect, useMemo, useState } from 'react';
import { useParams } from 'react-router-dom';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { EmployeeSalary } from '../../types/employeeSalary.types';

export default function EmployeeInfo() {
    const { id } = useParams();
    const [loading, setLoading] = useState(true);
    const [data, setData] = useState<EmployeeSalary | null>(null);

    const employeeId = useMemo(() => (id ? String(id) : ''), [id]);

    useEffect(() => {
        let cancelled = false;
        const load = async () => {
            if (!employeeId) return;
            setLoading(true);
            try {
                const res = await apiGet<{ data: EmployeeSalary }>({
                    endpoint: endpoints.employee.salary + employeeId,
                    queryParams: {
                        month: new Date().getMonth() + 1,
                        year: new Date().getFullYear(),
                    },
                });
                if (!cancelled) setData(res.data.data);
            } catch {
                if (!cancelled) setData(null);
            } finally {
                if (!cancelled) setLoading(false);
            }
        };
        load();
        return () => {
            cancelled = true;
        };
    }, [employeeId]);

    return (
        <div className="flex flex-row items-start w-full mt-6 ">
            <div className="flex-2">
                <p className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal bg-white-blue-100">
                    اسم الموظف
                </p>
                <div className="flex flex-row justify-start items-center gap-4 text-sm px-4 py-3 text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    <img src={adel} alt="" className="rounded-full w-10 h-10 object-cover" />
                    <div className="flex flex-col gap-1 text-nowrap">
                        <p className="tracking-normal text-primery-blue-900 font-medium text-sm">
                            {loading ? 'جاري التحميل…' : data?.name || '—'}
                        </p>
                        <p className="tracking-normal text-white-blue-800 font-normal text-sm">
                            {data ? `${data.position} - ${data.branch?.name ?? ''}` : '—'}
                        </p>
                    </div>
                </div>
            </div>
            <div className="flex-1">
                <p className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal bg-white-blue-100">
                    كود الموظف
                </p>
                <p className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] p-4">
                    {data?.id ?? '—'}
                </p>
            </div>
            <div className="flex-1">
                <p className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal bg-white-blue-100">
                    قسم الموظف
                </p>
                <p className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] p-4">
                    {data?.branch?.name ?? '—'}
                </p>
            </div>
            <div className="flex-1">
                <p className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal bg-white-blue-100">
                    المسمى الوظيفي
                </p>
                <p className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] p-4">
                    {data?.position ?? '—'}
                </p>
            </div>
            <div className="flex-1">
                <p className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal bg-white-blue-100">
                    تاريخ التعين
                </p>
                <p className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] p-4">—</p>
            </div>
            <div className="flex-1">
                <p className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal bg-white-blue-100">
                    اجمالي الرواتب
                </p>
                <p className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] p-4">
                    {data?.net_salary != null ? `${data.net_salary} ر.س` : '—'}
                </p>
            </div>
        </div>
    );
}
